//! Runtime support for projects generated by the `trust` compiler.
//!
//! Only what generated code actually uses lives here: the domain/storage
//! contracts (`EntityId`, `UseCase`, `Storage` and its list query types),
//! the Postgres connection wrapper (`SQLConnector`) and the HTTP layer
//! (`HttpPresenter`, `HttpError`, `HttpResult`, `start_http_server`).

mod http;
mod sql;
mod storage;

pub use http::{HttpError, HttpPresenter, HttpResult, start_http_server};
pub use sql::{SQLConnector, SQLError};
pub use storage::{Storage, StorageListQuery, StoragePredicate, StoragePredicateOperator};

/// Primary key of every generated entity.
pub type EntityId = i64;

/// A use case: takes the calling user's id and an input, yields an output.
pub trait UseCase<I, O, E> {
    fn execute(&self, user: i64, input: I) -> impl std::future::Future<Output = Result<O, E>> + Send;
}
